window.ScripturaLexicons.BDAG_PART_0291 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-01\" data-source=\"BDAG\" data-search=\"ποθητός, ή, όν adjetivo ansiado, muito amado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποθητός, ή, όν</td><td>adjetivo</td><td>ansiado, muito amado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-02\" data-source=\"BDAG\" data-search=\"πόθος, ου, ὁ substantivo masculino anseio, desejo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόθος, ου, ὁ</td><td>substantivo masculino</td><td>anseio, desejo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-03\" data-source=\"BDAG\" data-search=\"ποῖ advérbio interrogativo onde?, aonde? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποῖ</td><td>advérbio interrogativo</td><td>onde?, aonde?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-04\" data-source=\"BDAG\" data-search=\"ποία, ας, ἡ substantivo feminino erva, relva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποία, ας, ἡ</td><td>substantivo feminino</td><td>erva, relva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-05\" data-source=\"BDAG\" data-search=\"ποιέω verbo fazer, produzir, realizar, causar, praticar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποιέω</td><td>verbo</td><td>fazer, produzir, realizar, causar, praticar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-06\" data-source=\"BDAG\" data-search=\"ποίημα, ατος, τό substantivo neutro obra, criação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποίημα, ατος, τό</td><td>substantivo neutro</td><td>obra, criação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-07\" data-source=\"BDAG\" data-search=\"ποίησις, εως, ἡ substantivo feminino ação, execução, obra, criação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποίησις, εως, ἡ</td><td>substantivo feminino</td><td>ação, execução, obra, criação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-08\" data-source=\"BDAG\" data-search=\"ποιητής, οῦ, ὁ substantivo masculino criador, poeta, praticante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποιητής, οῦ, ὁ</td><td>substantivo masculino</td><td>criador, poeta, praticante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-09\" data-source=\"BDAG\" data-search=\"ποικιλία, ας, ἡ substantivo feminino variedade, diversidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποικιλία, ας, ἡ</td><td>substantivo feminino</td><td>variedade, diversidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-10\" data-source=\"BDAG\" data-search=\"ποικίλος, η, ον adjetivo variado, multiforme, multicolorido, astuto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποικίλος, η, ον</td><td>adjetivo</td><td>variado, multiforme, multicolorido, astuto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-11\" data-source=\"BDAG\" data-search=\"ποιμαίνω verbo apascentar, pastorear, governar, cuidar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποιμαίνω</td><td>verbo</td><td>apascentar, pastorear, governar, cuidar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-12\" data-source=\"BDAG\" data-search=\"ποιμενικός, ή, όν adjetivo pastoril, relativo a pastor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποιμενικός, ή, όν</td><td>adjetivo</td><td>pastoril, relativo a pastor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-13\" data-source=\"BDAG\" data-search=\"ποιμήν, ένος, ὁ substantivo masculino pastor, guardião, dirigente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποιμήν, ένος, ὁ</td><td>substantivo masculino</td><td>pastor, guardião, dirigente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-14\" data-source=\"BDAG\" data-search=\"ποίμνη, ης, ἡ substantivo feminino rebanho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποίμνη, ης, ἡ</td><td>substantivo feminino</td><td>rebanho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-15\" data-source=\"BDAG\" data-search=\"ποίμνιον, ου, τό substantivo neutro rebanho, comunidade sob um dirigente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποίμνιον, ου, τό</td><td>substantivo neutro</td><td>rebanho, comunidade sob um dirigente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-16\" data-source=\"BDAG\" data-search=\"ποῖος, α, ον pronome interrogativo de que espécie?, qual?, que? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ποῖος, α, ον</td><td>pronome interrogativo</td><td>de que espécie?, qual?, que?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-17\" data-source=\"BDAG\" data-search=\"πολεμέω verbo guerrear, combater, hostilizar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολεμέω</td><td>verbo</td><td>guerrear, combater, hostilizar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-18\" data-source=\"BDAG\" data-search=\"πόλεμος, ου, ὁ substantivo masculino guerra, batalha, conflito, contenda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόλεμος, ου, ὁ</td><td>substantivo masculino</td><td>guerra, batalha, conflito, contenda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-19\" data-source=\"BDAG\" data-search=\"πολιά, ᾶς, ἡ substantivo feminino velhice BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>velhice</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0291-20\" data-source=\"BDAG\" data-search=\"πολιορκία, ας, ἡ substantivo feminino cerco, aflição, tribulação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολιορκία, ας, ἡ</td><td>substantivo feminino</td><td>cerco, aflição, tribulação</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0291-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποθητός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποθητός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (sobre a formação, v. <span class=\"greek\">ποθέω</span>, cf. Hom. <span class=\"greek\">ποθή</span>; Aelian, NA 7, 3; Alciphron 3, 39, 2; IG VII 3434; Ramsay, Phrygia I/2 p. 386 linha 3 <span class=\"greek\">τέκνα</span> <span class=\"greek\">π</span>.; Just., D. 57, 4; Mel., P. 26, 186), ansiado, muito amado IRo 10:1; ISm 13:2; IPol 8:3.—DELG s.v. <span class=\"greek\">ποθέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόθος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόθος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (sobre a formação, v. <span class=\"greek\">ποθέω</span>; Hom.+; TestDan 4:5; TestJos 14:4; ApcEsdr 7:16 p. 33, 4 Tdf.; Philo; Jos., Ant. 12, 242; 15, 18; Mel., HE 4, 26, 13), interesse profundamente sentido por algo, anseio, aspiração, desejo: <span class=\"greek\">ἀκόρεστος</span> <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀγαθοποιίαν</span> um anseio insaciável de fazer o bem 1 Cl 2:2 (<span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> como Ps 9:24 Aq.; SibOr 2, 112).—Schmidt, Syn. III 596–601, <span class=\"greek\">ἐπιθυμία</span>. DELG s.v. <span class=\"greek\">ποθέω</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποῖ</h1><div class=\"entry-meta\"><span>advérbio interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποῖ</span>, adv. interrogativo (Theognis et al.; Celsus 6, 11; Jos., Ant. 1, 197; 16, 373), onde? aonde? 1 Cl 28:4.—DELG s.v. <span class=\"greek\">πο</span>-.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (forma dórica, atestável desde Pind., também SIG 1169, 121 [III a.C.]; Mal 3:2 v.l.; Jer 2:22 v.l., em lugar do ático <span class=\"greek\">πόα</span>, jônico e épico <span class=\"greek\">ποίη</span>. V. Lob., Phryn. 496), relva, erva, erva daninha; este sentido foi anteriormente admitido por vezes para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:14</a> (Exp. 7ª série, 10, 566); mas <span class=\"greek\">ποία</span> nessa passagem é mais bem entendido como o fem. de <span class=\"greek\">ποῖος</span> (1a<span class=\"greek\">γ</span>).—DELG s.v. <span class=\"greek\">πόα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποιέω</span> (Hom.+) imperf. <span class=\"greek\">ἐποίουν</span>; fut. <span class=\"greek\">ποιήσω</span>; 1º aor. <span class=\"greek\">ἐποίησα</span>; perf. <span class=\"greek\">πεποίηκα</span>; mais-que-perf. <span class=\"greek\">πεποιήκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:7</a> (como IMagnMai 93b, 24; sobre a omissão do aumento, v. B-D-F §66, 1; Mlt-H. 190). Méd.: imperf. <span class=\"greek\">ἐποιούμην</span>; 1º aor. <span class=\"greek\">ἐποιησάμην</span>; perf. <span class=\"greek\">πεποίημαι</span> 1 Cl 1:1. Pass. (desapareceu quase inteiramente; B-D-F §315): 1º fut. <span class=\"greek\">ποιηθήσομαι</span>; 1º aor. 3ª pess. pl. <span class=\"greek\">ἐποιήθησαν</span> (En 22:9); perf. 3ª pess. sing. <span class=\"greek\">πεποίηται</span> (Ec 8:14; Tat. 11, 2), part. <span class=\"greek\">πεποιημένος</span> (Ec 1:14 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:27</a>. Termo polivalente, frequentemente sem significação semântica específica, empregado em referência a uma ampla gama de atividades que envolvem questões como trazer algo à existência, fazer algo acontecer ou simplesmente interagir de algum modo com diversas entidades.</p><p class=\"entry-text\">① Produzir algo material, fazer, fabricar, produzir <span class=\"greek\">τὶ</span> algo (Gen 6:14ff; 33:17 e outros; JosAs 16:8; GrBar 3:5 ‘construir’; ApcMos 20; Mel., P. 38, 261).</p><p class=\"entry-text\">ⓐ Da atividade humana: <span class=\"greek\">σκεῦος</span> 2 Cl 8:2. <span class=\"greek\">χιτῶνας</span>, <span class=\"greek\">ἱμάτια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:39</a>. <span class=\"greek\">εἰκόνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:14b</a>. <span class=\"greek\">θεούς</span> fazer deuses <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:40</a> (Ex 32:1). <span class=\"greek\">ναοὺς</span> <span class=\"greek\">ἀργυροῦς</span> 19:24. <span class=\"greek\">ἀνθρακιάν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:18</a>. <span class=\"greek\">τέσσαρα</span> <span class=\"greek\">μέρη</span> 19:23 (v. <span class=\"greek\">μέρος</span> 1a). <span class=\"greek\">πηλόν</span> 9:11, 14. <span class=\"greek\">σκηνὰς</span> armar tendas, construir cabanas (1 Ch 15:1; 2 Esdr 18: 16f; Jdth 8:5; Jos., Ant. 3, 79; Just., D. 127, 3 <span class=\"greek\">σκηνήν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:33</a>. <span class=\"greek\">ἁγίασμα</span> GJs 6:1; <span class=\"greek\">καταπέτασμα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ναῷ</span> 10:1; <span class=\"greek\">τὴν</span> <span class=\"greek\">πορφύραν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κόκκινον</span> 12:1.—Empregado com expressões preposicionais <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">αὐτὴν</span> (isto é, <span class=\"greek\">τὴν</span> <span class=\"greek\">σκηνὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μαρτυρίου</span>) <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τύπον</span> fazê-la (a tenda do testemunho) segundo o modelo (Ex 25:40) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:44</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a>. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> fazer algo de ou a partir de algo (isto é, de determinado material; Hdt. 2, 96; cf. X., An. 4, 5, 14; Theophr., HP 4, 2, 5; Ex 20:24f; 28:15; 29:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:15</a>; 9:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:21</a>.</p><p class=\"entry-text\">ⓑ Da atividade divina, especificamente da atividade criadora de Deus, criar (Hes., Op. 109; Heraclitus, Fgm. 30 <span class=\"greek\">κόσμον</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">τις</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">ἐποίησεν</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἦν</span> <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔσται</span>; Pla., Tim. 76c <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιῶν</span> ‘o Criador’; Epict. 1, 6, 5; 1, 14, 10; 2, 8, 19 <span class=\"greek\">σε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">πεποίηκε</span>; 4, 1, 102; 107; 4, 7, 6 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">πεποίηκεν</span>; Ael. Aristid. 43, 7 K.=1 p. 2 D.: <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐποίησεν</span>; Herm. Wr. 4, 1. Na LXX frequentemente por בָּרָא, também Wsd 1:13; 9:9; Sir 7:30; 32:13; Tob 8:6; Jdth 8:14; Bar 3:35; 4:7; 2 Macc 7:28; Aristobulus em Eus., PE13, 12, 12 [pp. 182 e 184 Holladay]; JosAs 9:5; Philo, Sacr. Abel. 65 e frequentemente; SibOr 3, 28 e Fgm. 3, 3; 16; Just., A II, 5, 2 e outros), com ac. <span class=\"greek\">ἡ</span> <span class=\"greek\">χείρ</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.50\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:50</a> (Is 66:2). <span class=\"greek\">τοὺς</span> <span class=\"greek\">αἰῶνας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:2</a> (v. <span class=\"greek\">αἰών</span> 3). <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> (Epict. 4, 7, 6 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">πεποίηκεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">ὅλον</span>; Sallust. 5 p. 10, 29; Wsd 9:9; TestAbr A 10 p. 88, 21 [Stone p. 24]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:24</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (cf. Ael. Aristid. acima; Gen 1:1; Ex 20:11; Ps 120:2; 145:6; Is 37:16; Jer 39:17 et al.; TestJob 2:4; Jos., C. Ap. 2, 121; Aristobulus acima) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:24</a>; 14:15b; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:7</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> PtK 2 p. 13, 26 (JosAs 12, 2; Just., D. 55, 2; v. também Ael. Aristid. acima). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:40</a> é classificado aqui por muitos. Da relação de Jesus com Deus, <span class=\"greek\">Ἰησοῦν</span>, <span class=\"greek\">πιστὸν</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ποιήσαντι</span> <span class=\"greek\">αὐτόν</span>=que o designou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:2</a> (cf. Is 17:7).—Com um segundo ac., o do predicativo (PSI 435, 19 [258 a.C.] <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Σάραπις</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">μείζω</span> <span class=\"greek\">ποιήσῃ</span>) <span class=\"greek\">ἄρσεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θῆλυ</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">αὐτούς</span> (Deus) criou-os macho e fêmea <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:4b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:6</a> (ambos Gen 1:27c).—Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:27</a>.—<span class=\"greek\">ὁ</span> <span class=\"greek\">ποιήσας</span> o Criador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:4a</a> v.l.</p><p class=\"entry-text\">② Empreender ou fazer algo que produz um acontecimento, estado ou condição, fazer, causar, ocasionar, realizar, preparar etc.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">ἔργα</span> <span class=\"greek\">π</span>. praticar obras, também no sing. (como JosAs 29:3 <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιήσῃς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τοῦτο</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">π</span>. fazer como Abraão fez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:39</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ὑμῶν</span> v. 41; cf. 10:37. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρῶτα</span> <span class=\"greek\">ἔργα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a>. <span class=\"greek\">ἔργον</span> cometer um ato <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:2</a> v.l. <span class=\"greek\">ἔργον</span> <span class=\"greek\">ποίησον</span> <span class=\"greek\">εὐαγγελιστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:5</a> (v. <span class=\"greek\">ἔργον</span> 2).—<span class=\"greek\">ἔργον</span> ou <span class=\"greek\">ἔργα</span> referem-se por vezes a feitos maravilhosos: <span class=\"greek\">ἓν</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἐποίησα</span> fiz apenas um feito (maravilhoso) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:21</a>. Pl. 14:12a; cf. v. 12bc. Isso ilustra a transição para</p><p class=\"entry-text\">ⓑ Fazer, realizar milagres <span class=\"greek\">δυνάμεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:22</a>; 13:58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:11</a> (Just., A I, 26, 2 e outros); sing. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:5</a>; 9:39. <span class=\"greek\">θαυμάσια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:15</a> (cf. Sir 31:9). <span class=\"greek\">μεγάλα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαυμάσια</span> AcPl Ha 8, 33=BMM verso 5f (Just., A I, 62, 4). <span class=\"greek\">σημεῖα</span> (Ex 4:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:23</a>; 3:2; 7:31; 9:16; 11:47b; 20:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:13a</a>; 16:14; 19:20. Sing. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:30</a>; 10:41. <span class=\"greek\">τέρατα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σημεῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:8</a>; 7:36. <span class=\"greek\">ὅσα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:8</a>; 6:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:10</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:39</a>; 14:11.</p><p class=\"entry-text\">ⓒ De condições, ocasionar etc.: <span class=\"greek\">εἰρήνην</span> fazer, estabelecer a paz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:18</a> (cf. 2 Macc 1:4). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔκβασιν</span> proporcionar uma saída <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13</a> (sobre o gen. seguinte do inf. com artigo, v. B-D-F §400, 2; Rob. 1067). <span class=\"greek\">ἐπίστασιν</span> <span class=\"greek\">ὄχλου</span> provocar uma perturbação entre o povo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:12</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">σκάνδαλα</span> criar dificuldades <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:17</a>. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:20</a> v.l. KRomaniuk, ETL 69, ’93, 140f.—Com dat. de vantagem <span class=\"greek\">ἐποίουν</span> <span class=\"greek\">χαρὰν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀδελφοῖς</span> proporcionavam alegria aos membros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:3</a> (v. <span class=\"greek\">ἀδελφός</span> 2a).</p><p class=\"entry-text\">ⓓ Empregado com um substantivo como perífrase de um verbo simples de ação (v. 7a abaixo; B-D-F §310, 1.—<span class=\"greek\">ποιέω</span> em tais combinações já em IPriene 8, 63 [c. 328 a.C.], também Plut., Crass. 551 [13, 6]; v. <span class=\"greek\">ἑορτή</span>, fim). <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ᾆσμα</span> GJs 6:3. <span class=\"greek\">διαθήκην</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:9</a> (Jer 38:32 cód. Q; cf. Is 28:15; TestAbr A 8 p. 86, 6 [Stone p. 20] <span class=\"greek\">διάταξιν</span>). <span class=\"greek\">π</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκδίκησιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:7f</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:24</a> (v. <span class=\"greek\">ἐκδίκησις</span> 1). <span class=\"greek\">ἐνέδραν</span> 25:3. <span class=\"greek\">κοπετόν</span> 8:2. <span class=\"greek\">κρίσιν</span> (v. <span class=\"greek\">κρίσις</span> 1a<span class=\"greek\">α</span> e <span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:27</a>; Jd 15. <span class=\"greek\">θρῆνον</span> GJs 3:1. <span class=\"greek\">κυνηγίαν</span> AcPl Ha 1, 33. <span class=\"greek\">λύτρωσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.68\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:68</a>. <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ποιεῖν</span> (v.l. <span class=\"greek\">ὁδοποιεῖν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:23</a> (<span class=\"greek\">ὁδός</span> 2). <span class=\"greek\">π</span>. (<span class=\"greek\">τὸν</span>) <span class=\"greek\">πόλεμον</span> (<span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>) guerrear (contra alguém) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:7</a>; 12:17; 13:7 (Da 7:8 LXX; 7:21 Theod.; Gen 14:2). <span class=\"greek\">πρόθεσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:11</a>; <span class=\"greek\">συμβούλιον</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:6</a> v.l.; 15:1; <span class=\"greek\">συστροφήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:12</a>; cf. v. 13. <span class=\"greek\">φόνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:7</a> (cf. Dt 22:8; Callinicus, Vi. Hyp. 98, 21 Bonn; TestAbr B 10 p. 115, 4 [Stone p. 78, 4]).—<span class=\"greek\">τὸ</span> <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινι</span> v. 15, v. <span class=\"greek\">ἱκανός</span> 1.</p><p class=\"entry-text\">ⓔ Aquilo que se faz é indicado pelo neut. de um adj. ou pron.: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">π</span>. fazer o que é bom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:3</a>; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:29</a>; <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">π</span>. fazer o bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:11</a> (Ps 33:15). <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:7b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:9</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">καλὰ</span> (<span class=\"greek\">καὶ</span> <span class=\"greek\">εὐάρεστα</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">αὐτοῦ</span>) 1 Cl 21:1. <span class=\"greek\">καλόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:17</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κακόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:4</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">κακά</span> 3:8. <span class=\"greek\">κακόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:7a</a> (<span class=\"greek\">κακὸν</span> <span class=\"greek\">μηδέν</span>; cf. SIG 1175, 20 <span class=\"greek\">κακόν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ποιῆσαι</span>). <span class=\"greek\">κακά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:12</a> (Ps 33:17). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀρεστὰ</span> <span class=\"greek\">αὐτῷ</span> (=<span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:29</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:21b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:22</a> (TestAbr A 15 p. 96, 12 [Stone p. 40] <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀρεστὰ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐποίησεν</span>). <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:23</a>; 10:31b; IEph 15:3.—<span class=\"greek\">ὅ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:7</a>, 27a. <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:13</a>, 14 v.l.; AcPl Ha 9, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:15f</a>, 20 (cf. Epict. 2, 26, 4 <span class=\"greek\">ὸ̔</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">ποιεῖ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:24f</a> (o sentido específico ‘sacrificar’ nesta passagem é rejeitado por TAbbott [JBL 9, 1890, 137–52], mas defendido por FMozley [ET 7, 1896, 370–86], AAndersen [D. Abendmahl in d. ersten zwei Jahrh. 1904] e K Goetz [D. Abendmahlsfrage2 1907]). <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a>. <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:23</a>; 23:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:10b</a>. <span class=\"greek\">αὐτά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:32</a>; 2:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:46</a>, 47b.—<span class=\"greek\">τί</span> <span class=\"greek\">ποιήσω</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:35</a> (TestAbr A 4 p. 81, 19 [Stone p. 10]; ParJer 6:14 <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσωμεν</span>; ApcEsdr 7:4 p. 32, 14 Tdf.). <span class=\"greek\">τί</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">ποιήσω</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:16</a>. <span class=\"greek\">τί</span> <span class=\"greek\">κακὸν</span> <span class=\"greek\">ἐποίησεν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:14</a>. <span class=\"greek\">τί</span> <span class=\"greek\">περισσὸν</span> <span class=\"greek\">ποιεῖτε</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:47a</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ποιεῖτε</span> <span class=\"greek\">τοῦτο</span>; que é isto que estais fazendo? ou por que estais fazendo isto? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:3</a> (GrBar 2:2 <span class=\"greek\">τί</span> <span class=\"greek\">ἐποίησας</span> <span class=\"greek\">τοῦτο</span>; v. B-D-F §299, 1; Rob. 736; 738; Rdm.2 25f). <span class=\"greek\">τί</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ποιεῖτε</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:15a</a> (como Demosth. 55, 5). <span class=\"greek\">τί</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">ὧδε</span> <span class=\"greek\">ποιεῖς</span>; Hv 1, 1, 5. Seguido de part. (B-D-F §414, 5; Rob. 1121) <span class=\"greek\">τί</span> <span class=\"greek\">ποιεῖτε</span> <span class=\"greek\">λύοντες</span>; que estais fazendo, desatando? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:5</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ποιεῖτε</span> <span class=\"greek\">κλαίοντες</span>; que estais fazendo, chorando? ou que pretendeis com esse choro? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:13</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσουσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">βαπτιζόμενοι</span>; que hão de fazer aqueles que se fazem batizar? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:29</a>.—Segue-se uma declaração daquilo que se deve fazer, em uma pergunta indireta <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ποιεῖς</span> <span class=\"greek\">ποίησον</span> faze o que tens de fazer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:27</a> (como Epict. 3, 21, 24 <span class=\"greek\">ποίει</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ποιεῖς</span>; 3, 23, 1; 4, 9, 18; TestJob 7:13).</p><p class=\"entry-text\">ⓕ De refeições ou banquetes e de festividades das quais um banquete é a parte principal, oferecer <span class=\"greek\">ἄριστον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:12</a>. <span class=\"greek\">δεῖπνον</span> (v. esse lema, b<span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:12</a>, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:2</a>; Hs 5, 2, 9. <span class=\"greek\">δοχήν</span> (v. <span class=\"greek\">δοχή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:29</a>; 14:13; GJs 6:2. <span class=\"greek\">γάμους</span> (v. <span class=\"greek\">γάμος</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:2</a> (JosAs 20:6).—Observar, celebrar (PFay 117, 12) a (festa da) Páscoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a> (v. <span class=\"greek\">πάσχα</span> 3). Também em conexão com <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑορτὴν</span> <span class=\"greek\">ποιῆσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:21</a> D certamente se tem em vista a Páscoa. Mas <span class=\"greek\">π</span>. é empregado também acerca de festas em geral (cf. X., Hell. 4, 5, 2 <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">Ἴσθμια</span>; 7, 4, 28 <span class=\"greek\">τὰ</span> <span class=\"greek\">Ὀλύμπια</span>).</p><p class=\"entry-text\">ⓖ Dos processos naturais de crescimento; na vida vegetal, brotar, produzir, dar, render <span class=\"greek\">καρπόν</span>, <span class=\"greek\">καρπούς</span> (Aristot., Plant. 1, 4, 819b, 31; 2, 10, 829a, 41; LXX [<span class=\"greek\">καρπός</span> 1a<span class=\"greek\">α</span>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a>; 7:17ab, 18, 19; 13:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>; 6:43ab; 8:8; 13:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2</a>; também em linguagem figurada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:8</a>; 21:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:8</a>. <span class=\"greek\">κλάδους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:32</a>. <span class=\"greek\">ἐλαίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:12a</a> (cf. Jos., Ant. 11, 50 <span class=\"greek\">ἄμπελοι</span>, <span class=\"greek\">αἳ</span> <span class=\"greek\">ποιοῦσιν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶνον</span>). <span class=\"greek\">π</span>. <span class=\"greek\">ὕδωρ</span> produzir água v. 12b (mas v. <span class=\"greek\">ἁλυκός</span>).—De capital que proporciona rendimento <span class=\"greek\">ἡ</span> <span class=\"greek\">μνᾶ</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">μνᾶς</span> a mina rendeu cinco minas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:18</a>. Também de uma pessoa que opera com capital, ganhar dinheiro (Ps.-Demosth. 10, 76; Polyb. 2, 62, 12) <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ἄλλα</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">τάλαντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:16</a> v.l.</p><p class=\"entry-text\">ⓗ Com ênfase na causalidade.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. O resultado da ação é indicado pelo ac. e inf.; fazer (com que), levar (alguém) a, fazer que (Hom. et al.; também inscrições [SIG IV p. 510a índice], papiros, LXX; TestJob 3:7; 42:6; ParJer 9:16f; ApcMos 16; Just., A I, 26, 5, D. 69, 6; 114, 1; Ath. 13, 2) <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">μοιχευθῆναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a>. <span class=\"greek\">ποιήσω</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">ἁλεεῖς</span> <span class=\"greek\">ἀνθρώπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:17</a>. Cf. 7:37b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:34</a> (obrigar alguém a jejuar); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:13b</a>.—<span class=\"greek\">ἵνα</span> ocupa o lugar do inf.: <span class=\"greek\">ποιήσω</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἥξουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:9</a>; cf. 13:12b, 16. <span class=\"greek\">ἵνα</span> sem ac. (TestAbr B 6 p. 110, 20 [Stone p. 68] <span class=\"greek\">ποίησον</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">φαγῶμεν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:15</a>.—<span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πεποιηκόσιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">περιπατεῖν</span> <span class=\"greek\">αὐτόν</span> a nós, como se tivéssemos feito com que ele andasse <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:12</a> (v. B-D-F §400, 7).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com duplo acusativo, do objeto e do predicativo (Hom. et al.; LXX; ApcEsdr 4:27 p. 38, 32 Tdf. <span class=\"greek\">λίθους</span> <span class=\"greek\">ἄρτους</span> <span class=\"greek\">ποιήσας</span>; Mel., P. 68, 494 <span class=\"greek\">ποιήσας</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἱεράτευμα</span> <span class=\"greek\">καινόν</span>), fazer de alguém ou de algo alguma coisa. Com substantivo como ac. predicativo: <span class=\"greek\">ποιήσω</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἁλιεῖς</span> <span class=\"greek\">ἀνθρώπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:19</a>. <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">αὐτὸν</span> (isto é, <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) <span class=\"greek\">ποιεῖτε</span> <span class=\"greek\">σπήλαιον</span> <span class=\"greek\">λῃστῶν</span> 21:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:46</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:15b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:16</a>; 4:46, 54; cf. 2:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:7</a> (Ps 103:4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:6</a>; 3:12 e outros. <span class=\"greek\">ποίησόν</span> <span class=\"greek\">με</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μισθίων</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:19</a>, 21 v.l. (cf. Gen 45:8; 48:20 e v. B-D-F §453, 4; Rob. 481). Se faltar o ac. do objeto, pode ser suprido pelo contexto como algo evidente: <span class=\"greek\">ἁρπάζειν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ποιήσωσιν</span> <span class=\"greek\">βασιλέα</span> tomá-lo à força, a fim de fazê-lo rei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:15</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:15</a>. Afirmar que alguém é alguma coisa, pretender que alguém seja alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:53</a>; 10:33; 19:7, 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:10</a>; 5:10. Cf. 5b.—Com adj. como ac. predicativo: <span class=\"greek\">εὐθείας</span> <span class=\"greek\">ποιεῖτε</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">τρίβους</span> (Is 40:3) endireitai as veredas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:4</a>. <span class=\"greek\">τρίχα</span> <span class=\"greek\">λευκὴν</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:36</a>. Cf. 12:16; 20:12b; 26:73; 28:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:11</a>, 15; 7:23; 16:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:14</a> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιήσας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀμφότερα</span> <span class=\"greek\">ἕν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:15</a>; 21:5. <span class=\"greek\">ἴσον</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ποιῶν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (com isso) declarando que era igual a Deus ou fazendo-se igual a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:18</a>.—Cf. o emprego da voz méd. em 7b abaixo.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Com adv. de lugar, mandar para fora <span class=\"greek\">ἔξω</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινα</span> pôr alguém para fora (=mandar para fora; cf. X., Cyr. 4, 1, 3 <span class=\"greek\">ἔξω</span> <span class=\"greek\">βελῶν</span> <span class=\"greek\">ποιεῖν</span>=‘pôr fora do alcance das flechas’) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:34</a>.</p><p class=\"entry-text\">③ Cumprir uma obrigação de natureza moral ou social, fazer, observar, cumprir, praticar, cometer.</p><p class=\"entry-text\">ⓐ Fazer, observar obedientemente a vontade ou a lei <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> etc. (JosAs 12:3; v. <span class=\"greek\">θέλημα</span> 1c<span class=\"greek\">γ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:21</a>; 12:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:34</a>; 6:38; 7:17; 9:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:7</a>, 9 (ambos Ps 39:9), 36; 13:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:17</a>; Pol 2:2; <span class=\"greek\">τὰ</span> <span class=\"greek\">θελήματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:35</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:22</a>; GEb 121, 34. <span class=\"greek\">π</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">θελήματα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:3</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:31</a>.—<span class=\"greek\">π</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:10</a> (Dt 27:26); v. 12 (cf. Lev 18:5).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:5</a>; 8:44. <span class=\"greek\">ἐκεῖνο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">προσταχθὲν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ποιήσωμεν</span> façamos aquilo que nos foi ordenado GMary 463, 27f (ParJer 6:9).—<span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">φανηρώσῃ</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ποιήσομεν</span> GJs 8:2.—<span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ποιεῖν</span> exercer autoridade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:12a</a>.</p><p class=\"entry-text\">ⓑ Fazer, praticar virtudes (cf. SIG 304, 41f <span class=\"greek\">τὰ</span> <span class=\"greek\">δίκαια</span>): <span class=\"greek\">π</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span> (<span class=\"greek\">ἀλήθεια</span> 2b) viver a verdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:21</a> (cf. 1QS 1:5 e outros); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:6</a>. (<span class=\"greek\">τὴν</span>) <span class=\"greek\">δικαιοσύνην</span> (<span class=\"greek\">δικαιοσύνη</span> 3a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:29</a>; 3:7, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:11</a>; 2 Cl 4:2; 11:7. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐντολά</span> Ro 22:14 v.l. (SGoranson, NTS 43, ’97, 154–57). Diferentemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:1</a> (<span class=\"greek\">δικαιοσύνη</span> 3b), que se agrupa com <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ἐλεημοσύνην</span> vv. 2a e 3a (v. <span class=\"greek\">ἐλεημοσύνη</span> 1); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:36</a>; 10:2; 24:17. <span class=\"greek\">π</span>. <span class=\"greek\">ἐγκράτειαν</span> 2 Cl 15:1. <span class=\"greek\">π</span>. <span class=\"greek\">χρηστότητα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:12</a> (Ps 13:1, 3; 52:4 v.l.). <span class=\"greek\">π</span>. <span class=\"greek\">ἔλεος</span> mostrar misericórdia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:13</a>; <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> para com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.72\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:72</a>; 10:37a (JosAs 23:4; v. <span class=\"greek\">ἔλεος</span> a e <span class=\"greek\">μετά</span> A2<span class=\"greek\">γ</span>ג).</p><p class=\"entry-text\">ⓒ Praticar, cometer, ser culpado de pecados e vícios (<span class=\"greek\">τὴν</span>) <span class=\"greek\">ἁμαρτίαν</span> (<span class=\"greek\">ἁμαρτία</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:4a</a>, 8, 9; pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:15</a> (TestAbr B 10 p. 115, 10 [Stone p. 78, 10]). <span class=\"greek\">ἁμάρτημα</span> (TestJob 11:3; ParJer 2:2; v. <span class=\"greek\">ἁμάρτημα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:18</a>. (<span class=\"greek\">τὴν</span>) <span class=\"greek\">ἀνομίαν</span> (<span class=\"greek\">ἀνομία</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:4b</a>; 1 Cl 16:10 (Is 53:9). <span class=\"greek\">βδέλυγμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ψεῦδος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:27</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρὸν</span> <span class=\"greek\">τοῦτο</span> GJs 13:1; cf. 13:2; 15:3f; <span class=\"greek\">ταῦτα</span> 15:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">καθήκοντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a>. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔξεστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:24</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:2</a>.</p><p class=\"entry-text\">ⓓ A maneira da ação é indicada mais precisamente por meio de um adv. (Jos., C. Ap. 2, 51). <span class=\"greek\">καλῶς</span> <span class=\"greek\">ποιεῖν</span> fazer o bem ou agir bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:37</a>, 38a (ApcMos 17). <span class=\"greek\">κρεῖσσον</span> <span class=\"greek\">π</span>. 7:38b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:8</a> (v. 5d abaixo), 19; <span class=\"greek\">φρονίμως</span> <span class=\"greek\">π</span>. agir prudentemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:8</a>; <span class=\"greek\">π</span>. <span class=\"greek\">οὕτως</span> fazer assim (Chariton 8, 6, 4 <span class=\"greek\">ποιήσομεν</span> <span class=\"greek\">οὕτως</span>=é assim que procederemos; JosAs 10:20; ApcMos 40; Mel., P. 13, 82) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:15</a>; 12:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:31</a> (<span class=\"greek\">καθὼς</span> … <span class=\"greek\">οὕτως</span> <span class=\"greek\">π</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:12</a>; B 12:7; GJs 7:2. <span class=\"greek\">π</span>. <span class=\"greek\">ὡσαύτως</span> proceder do mesmo modo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:5</a>; <span class=\"greek\">ὁμοίως</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:11</a>; 10:37b. <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑποκριταὶ</span> <span class=\"greek\">ποιοῦσιν</span> como fazem os dissimuladores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:2b</a>. <span class=\"greek\">καθὼς</span> <span class=\"greek\">ποιεῖτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:11</a>.—<span class=\"greek\">ποιεῖν</span> seguido de uma oração iniciada por <span class=\"greek\">ὡς</span>: <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">προσέταξεν</span> fez como (o anjo) havia ordenado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:24</a>; cf. 26:19. Ou a oração começa com <span class=\"greek\">καθώς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:15b</a> (TestJob 7:9). Para GJs 17:1, v. 5e.</p><p class=\"entry-text\">ⓔ A maneira da ação é indicada mais precisamente por uma expressão preposicional. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τι</span> fazer ou agir de acordo com algo (SIG 915, 13 <span class=\"greek\">π</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">συνθήκας</span>; 1016, 6; PLille 4, 6; 22 [III a.C.]; BGU 998 II, 12 [II a.C.] <span class=\"greek\">π</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">προγεγραμμένα</span>) <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">αὐτῶν</span> como eles fazem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:3b</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:27</a>. Também <span class=\"greek\">π</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span>: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> 12:47.</p><p class=\"entry-text\">④ Fazer algo a outrem ou a alguma coisa, fazer algo a/com, acerca de comportamento que envolve outros, <span class=\"greek\">π</span>. <span class=\"greek\">τι</span> com alguma indicação da pessoa (ou coisa) com quem se faz algo; a ação pode resultar em benefício ou prejuízo dessa pessoa:</p><p class=\"entry-text\">ⓐ Neutro <span class=\"greek\">π</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινα</span> fazer algo com alguém (duplo ac. como Demosth. 23, 194 <span class=\"greek\">τὶ</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>) <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσω</span> <span class=\"greek\">Ἰησοῦν</span>; que farei de Jesus? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:22</a>. <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ποιήσωμεν</span>; que faremos, então, a respeito de (Maria)? GJs 8:2; cf. 14:1; 17:1. <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσεις</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀγρόν</span>; que farás com o terreno? Hs 1:4 (ParJer 3:9 <span class=\"greek\">τί</span> <span class=\"greek\">θέλει</span> <span class=\"greek\">ποιήσω</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἅγια</span> <span class=\"greek\">σκεύη</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:12</a>.—B-D-F §157, 1; Rob. 484.—Neutra é também a expressão <span class=\"greek\">π</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> fazer algo a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:26</a>; 12:16; 13:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:16</a>. Igualmente a forma passiva do conhecido dito de Jesus <span class=\"greek\">ὡς</span> <span class=\"greek\">ποιεῖτε</span>, <span class=\"greek\">οὕτω</span> <span class=\"greek\">ποιηθήσεται</span> <span class=\"greek\">ὑμῖν</span> como fazeis (seja bem, seja mal), assim vos será feito 1 Cl 13:2.</p><p class=\"entry-text\">ⓑ Em benefício de alguém: <span class=\"greek\">π</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> (Diod S 18, 51, 3; TestAbr B 12 p. 116, 19 [Stone p. 80]; ParJer 3:12; ApcMos 3): <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">θέλητε</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ποιῶσιν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12a</a>. <span class=\"greek\">τί</span> <span class=\"greek\">θέλετε</span> <span class=\"greek\">ποιήσω</span> <span class=\"greek\">ὑμῖν</span>; que quereis que eu vos faça? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:32</a>.—25:40; cf. v. 45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:19f</a>; 7:12; 10:35f, 51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:49</a>; 8:39ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:15a</a>.—<span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:10</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> (B-D-F §227, 3, referências adicionais B-D-R) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:27</a>; 15:4 (TestJob 1:4; sobre a construção com <span class=\"greek\">μετά</span>, v. 3b acima e cf. BGU 798, 7; 948, 8).</p><p class=\"entry-text\">ⓒ Em prejuízo de alguém: <span class=\"greek\">π</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> (Gen 20:9; JosAs 28:10 <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιήσητε</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">κακόν</span>; ApcMos 42) <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσει</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">γεωργοῖς</span>; que fará aos viticultores? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:40</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:11</a>; 20:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:6</a> (Ps 117:6); GJs 9:2.—<span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> (PSI 64, 20; 22 [I a.C.] <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ποιήσειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">φάρμακα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:21</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:31</a>.</p><p class=\"entry-text\">ⓓ Com dat. e adv. <span class=\"greek\">ἐποίησαν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὡσαύτως</span> trataram-nos do mesmo modo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:36</a>. <span class=\"greek\">οὕτως</span> <span class=\"greek\">μοι</span> <span class=\"greek\">πεποίηκεν</span> <span class=\"greek\">κύριος</span> o Senhor procedeu assim para comigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:25</a>; cf. 2:48; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:35</a>. <span class=\"greek\">εὖ</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:7</a>. <span class=\"greek\">καλῶς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:27</a>. <span class=\"greek\">ὁμοίως</span> <span class=\"greek\">π</span>. <span class=\"greek\">τινι</span> 6:31b.—Em expressão coloquial condensada (<span class=\"greek\">ποιεῖν</span>) <span class=\"greek\">καθὼς</span> <span class=\"greek\">ἐποίει</span> <span class=\"greek\">αὐτοῖς</span> (fazer) como costumava fazer por eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:8</a> (v. <span class=\"greek\">εὐποιί̈α</span> 1).</p><p class=\"entry-text\">ⓔ Com dat. e prep. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">ἐποίουν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">προφήταις</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πατέρες</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:23</a>; cf. v. 26.</p><p class=\"entry-text\">⑤ Fazer, com variações em expressões especializadas.</p><p class=\"entry-text\">ⓐ Obter ou conseguir algo para si, prover-se de algo. <span class=\"greek\">ποιήσατε</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">βαλλάντια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:33</a>; <span class=\"greek\">φίλους</span> 16:9 (cf. X., An. 5, 5, 12 <span class=\"greek\">φίλον</span> <span class=\"greek\">ποιεῖσθαί</span> <span class=\"greek\">τινα</span>).—Sem dat. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">μαθητὰς</span> <span class=\"greek\">ποιεῖ</span> Jesus conquistava discípulos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:1</a>.</p><p class=\"entry-text\">ⓑ De construção mental, admitir, supor, tomar como exemplo (Hdt. et al.) com duplo ac. (Pla., Theaet. 197d) <span class=\"greek\">ποιήσατε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δένδρον</span> <span class=\"greek\">καλόν</span> suponde que a árvore seja boa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:33a</a>; cf. v. 33b.</p><p class=\"entry-text\">ⓒ Com ac. de tempo, passar, permanecer (Anth. 11, 330; PSI 362, 15 [251/250 a.C.]; UPZ 70, 21; PFlor 137, 7 [III d.C.] <span class=\"greek\">ἡμέραν</span>, <span class=\"greek\">ἥν</span> <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">ἐκεῖ</span>; PGen 54, 18 <span class=\"greek\">τρεῖς</span> <span class=\"greek\">ἡμέρας</span>; Pr 13:23; Ec 6:12; Tob. 10:7 BA; TestJob 20:5; 31:4; ParJer 6:16; ApcMos 37 <span class=\"greek\">ὥρας</span> <span class=\"greek\">τρεῖς</span>; Jos. Ant. 6, 18 <span class=\"greek\">μῆνας</span> <span class=\"greek\">τέσσαρας</span>; cf. nosso coloquial inglês ‘do time’ [cumprir pena]. Demosth. 19, 163 e Pla., Phileb. 50d são citados erroneamente nesse contexto, como demonstra WSchulze, Graeca Latina 1901, 23f) <span class=\"greek\">χρόνον</span> (Dionys. Hal. 4, 66; ParJer 7:33; ApcMos 31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:33</a>; 18:23. <span class=\"greek\">μῆνας</span> <span class=\"greek\">τρεῖς</span> 20:3. <span class=\"greek\">τρεῖς</span> <span class=\"greek\">μῆνας</span> GJs 12:3. <span class=\"greek\">νυχθήμερον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:25</a>. <span class=\"greek\">ἐνιαυτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:13</a> (TestJob 21:1 <span class=\"greek\">ἔτη</span>).</p><p class=\"entry-text\">ⓓ <span class=\"greek\">καλῶς</span> <span class=\"greek\">ποιεῖν</span> seguido de part., fazer bem se, fazer bem em, como fórmula por vezes=por favor (v. <span class=\"greek\">καλῶς</span> 4a e cf. SIG 561, 6f <span class=\"greek\">καλῶς</span> <span class=\"greek\">ποιήσειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πολίτας</span> <span class=\"greek\">προσδεξαμένους</span>; UPZ 110, 11 [164 a.C.]; POxy 300, 5 [I d.C.]; 525, 7; Hdt. 5, 24 <span class=\"greek\">εὖ</span> <span class=\"greek\">ἐποίησας</span> <span class=\"greek\">ἀφικόμενος</span>; SIG 598e, 8f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a>; 3J 6; GEg 252, 53.—Semelhantemente <span class=\"greek\">καλῶς</span> <span class=\"greek\">ποιεῖν</span>, <span class=\"greek\">εἰ</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:8</a> (cf. PPetr II, 11 [1], 1 <span class=\"greek\">καλῶς</span> <span class=\"greek\">ποιεῖς</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">ἔρρωσαι</span>).</p><p class=\"entry-text\">ⓔ <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ποιήσει</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">βούλεται</span> este dia do Senhor transcorrerá como (o Senhor) deseja GJs 17:1 (deStrycker cita <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:34</a> para a construção); se for adotada a acentuação <span class=\"greek\">αὐτή</span>, traduza-se: o próprio dia do Senhor fará com que as coisas aconteçam como (o Senhor) deseja.</p><p class=\"entry-text\">⑥ Estar ativo de algum modo, trabalhar, atuar, em uso absoluto (X., An. 1, 5, 8; Ruth 2:19), com ac. de tempo (Socrat., Ep. 14, 8 <span class=\"greek\">ποιήσας</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">τριάκοντα</span>) <span class=\"greek\">μίαν</span> <span class=\"greek\">ὥραν</span> <span class=\"greek\">ἐποίησαν</span> trabalharam apenas uma hora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:12a</a>. <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">μῆνας</span> atuar durante meses <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:5</a>.—Por vezes não se tem em vista uma ação ou atividade geral, mas a realização de algo bastante definido. O ac. correspondente é facilmente suprido pelo contexto: <span class=\"greek\">λέγουσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ποιοῦσιν</span> dizem(-no), mas não (o) fazem ou observam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:3c</a> (o contraste não é entre falar [<span class=\"greek\">λαλεῖν</span>] e agir em geral).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:10f</a> (v. Betz, 2 Cor p. 64); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:24</a>.</p><p class=\"entry-text\">⑦ Fazer algo para si ou por si mesmo, voz méd.</p><p class=\"entry-text\">ⓐ Principalmente como perífrase da ideia verbal simples (v. 2d) <span class=\"greek\">ἀναβολὴν</span> <span class=\"greek\">ποιεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:17</a> (v. <span class=\"greek\">ἀναβολή</span>). <span class=\"greek\">ἐκβολὴν</span> <span class=\"greek\">ποιεῖσθαι</span> 27:18 (v. <span class=\"greek\">ἐκβολή</span>); <span class=\"greek\">αὔξησιν</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:16</a>; <span class=\"greek\">δέησιν</span> ou <span class=\"greek\">δεήσεις</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:1</a> (v. <span class=\"greek\">δέησις</span>). <span class=\"greek\">διαλογισμοὺς</span> <span class=\"greek\">π</span>. 1 Cl 21:3; <span class=\"greek\">τὰς</span> <span class=\"greek\">διδασκαλίας</span> Papias (2:15); <span class=\"greek\">τὴν</span> <span class=\"greek\">ἕνωσιν</span> <span class=\"greek\">π</span>. IPol 5:2; <span class=\"greek\">ἐπιστροφὴν</span> <span class=\"greek\">π</span>. 1 Cl 1:1 (<span class=\"greek\">ἐπιστροφή</span> 1); <span class=\"greek\">καθαρισμὸν</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a> (<span class=\"greek\">καθαρισμός</span> 2). <span class=\"greek\">κοινωνίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:26</a>. <span class=\"greek\">κοπετόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:2</a> v.l.; <span class=\"greek\">λόγον</span> (Isocr., Ep. 2, 2; Just., D. 1, 3 e outros) 1:1; 11:2 D; 20:24 v.l. (sobre essas três passagens, v. <span class=\"greek\">λόγος</span>: 1b; 1a<span class=\"greek\">γ</span> e 1a<span class=\"greek\">α</span>, fim). <span class=\"greek\">μνείαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:2</a>; Phlm 4 (<span class=\"greek\">μνεία</span> 2). <span class=\"greek\">μνήμην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:15</a> (v. <span class=\"greek\">μνήμη</span> 1). <span class=\"greek\">μονήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:23</a> (<span class=\"greek\">μονή</span> 1). <span class=\"greek\">νουθέτησιν</span> 1 Cl 56:2 (Just., A I, 67, 4). <span class=\"greek\">ὁμιλίαν</span> IPol 5:1 (<span class=\"greek\">ὁμιλία</span> 2). <span class=\"greek\">ποιεῖσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παραβολήν</span> AcPlCor 2:28. <span class=\"greek\">πορείαν</span> <span class=\"greek\">π</span>. (=<span class=\"greek\">πορεύεσθαι</span>; cf. X., An. 5, 6, 11, Cyr. 5, 2, 31; Plut., Mor. 571e; Jos., Vi. 57; 2 Macc 3:8; 12:10; Ar. 4, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:22</a>. <span class=\"greek\">πρόνοιαν</span> <span class=\"greek\">π</span>. tomar providências, cuidar (Isocr. 4, 2 e 136; Demosth., Prooem. 16; Ps.-Demosth. 47, 80; Polyb. 4, 6, 11; Dion. Hal. 5, 46; Aelian, VH 12, 56. Frequentemente em inscrições e papiros [especialmente de pessoas zelosas pelo bem público]; Da 6:19 <span class=\"greek\">προν</span>. <span class=\"greek\">ποιούμενος</span> <span class=\"greek\">αὐτοῦ</span>; Jos., Bell. 4, 317, C. Ap. 1, 9; Ar. 13, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:14</a>; Papias (2:15). <span class=\"greek\">προσκλίσεις</span> <span class=\"greek\">π</span>. 1 Cl 47:3; <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">π</span>. empenhar-se (Hdt. 1, 4; 5, 30 <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">ποιούμενος</span>; 9, 8; Pla., Euthyd. 304e, Leg. 1, 628e; Isocr. 5, 45 <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σπ</span>.̀ <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">ποιεῖσθαι</span>; Polyb. 1, 46, 2 e outros; Diod S 1, 75, 1; Plut., Mor. 4e; SIG 539A, 15f; 545, 14 <span class=\"greek\">τὴν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σπ</span>.̀ <span class=\"greek\">ποιούμενος</span>; PHib 71, 9 [III a.C.] <span class=\"greek\">τ</span>. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σπ</span>. <span class=\"greek\">ποίησαι</span>; 44, 8) Jd 3. <span class=\"greek\">συνελεύσεις</span> <span class=\"greek\">ποιεῖσθαι</span> reunir-se, encontrar-se 1 Cl 20:10 (Just., A I, 67, 7). <span class=\"greek\">συνωμοσίαν</span> <span class=\"greek\">ποιεῖσθαι</span> formar uma conspiração (Polyb. 1, 70, 6; Herodian 7, 4, 3; SIG 526, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:13</a>.—Cf. o emprego da voz ativa 2d.</p><p class=\"entry-text\">ⓑ Com duplo ac., do objeto e do predicativo (Lucian, Prom. Es in Verb. 6 <span class=\"greek\">σεμνοτάτας</span> <span class=\"greek\">ἐποιεῖτο</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">συνουσίας</span>; GDI 4629, II, 22; 25 [Lacônia]; Jos., Ant. 2, 263; v. 2h<span class=\"greek\">β</span>) <span class=\"greek\">βεβαίαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κλῆσιν</span> <span class=\"greek\">ποιεῖσθαι</span> tornar firme a vocação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:10</a>. <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">ποιοῦμαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">τιμίαν</span> <span class=\"greek\">ἐμαυτῷ</span> não considero minha vida algo de valor para mim mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:24</a>. Cf. o emprego da voz ativa 2h<span class=\"greek\">β</span>.—B. 538. Cf. <span class=\"greek\">πράσσω</span>. Schmidt, Syn. I 397–423. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποίημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποίημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ποιέω</span>; Hdt. et al.; SIG 532, 5; LXX; TestSol 2:1 L; TestAbr; TestJob 49:2f; ApcEsdr 2:24 p. 26, 17 Tdf.; ApcMos; apologistas, exceto Mel.), aquilo que é feito, obra, criação, em nossa literatura somente acerca das obras da criação divina (Aesop, Fab. 444 P.=142 H. <span class=\"greek\">ποιήματα</span>; Ps 142:5; TestSol 2:1 L; ApcEsdr; Philo, Det. Pot. Ins. 125 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ποιήματα</span>; Just., Tat., Ath. Cf. Aelian, NA 1, 53 <span class=\"greek\">π</span>. <span class=\"greek\">Προμηθέως</span>; Alex. Aphr., An. Mant. II 1 p. 112, 1, acerca das criações do Nous; diferentemente Ar. 13, 5 e Tat. 33, 1: poema) <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀόρατα</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ποιήμασι</span> <span class=\"greek\">νοούμενα</span> <span class=\"greek\">καθορᾶται</span> a natureza invisível (de Deus) é percebida com os olhos da mente por meio das coisas que (Deus) criou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:20</a> (sobre isso, v. a bibliografia sob <span class=\"greek\">ἀόρατος</span> e <span class=\"greek\">γνωστός</span> 2). Dos cristãos, <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">π</span>. somos criação (de Deus), isto é, (Deus) fez de nós aquilo que somos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:10</a>.—DELG s.v. <span class=\"greek\">ποιέω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποίησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποίησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ποιέω</span>. Hdt. et al.; inscrições, papiros, LXX)</p><p class=\"entry-text\">① O processo da atividade, ação, execução (Pla., Soph. 266d <span class=\"greek\">θείας</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">ποιήσεως</span>, Charm. 163e; Jos., Ant. 17, 94) <span class=\"greek\">μακάριος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ποιήσει</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἔσται</span> essa pessoa será bem-aventurada na prática <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:25</a>. De Deus: <span class=\"greek\">ποίησις</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">αὐτοῦ</span> 1 Cl 27:7 (Ps 18:2; cf. Just., D. 56, 10 <span class=\"greek\">πρὸ</span> <span class=\"greek\">ποιήσεως</span> <span class=\"greek\">κόσμου</span>).</p><p class=\"entry-text\">② O produto da atividade, obra, criação do artista (Aristoph., Pla. et al.; SIG 547, 48 [211/210 a.C.]; EpArist 57; Jos., C. Ap. 1, 12; Just., Tat., Ath.; acerca de poesia e navios Tat. 1, 1 e outros; Ath. 29, 1), em nossa literatura acerca do Artista divino (Proclus sobre Pla., Cratylus p. 21, 18f Pasqu.): Deus é misericordioso <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ποίησιν</span> <span class=\"greek\">αὐτοῦ</span> (Da 9:14 Theod.) Hm 4, 3, 5; 9:3.—DELG s.v. <span class=\"greek\">ποιέω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποιητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποιητής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ποιέω</span>)</p><p class=\"entry-text\">① Aquele que faz algo produzindo alguma coisa, artífice (de Deus Pla., Tim. 28c; Just., D. 56, 4 e outros <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span> <span class=\"greek\">ποιητής</span>; Tat., Ath.), depois especificamente poeta (assim Aristoph., Ran. 96; 1030; Pla., Phd. 61b e outros; frequentemente em inscrições [SIG IV 510b índice; OGI II 694b índice]; PHerm 125 B, 6; POsl 189, 13 [III d.C.]; TestSol; EpArist 31; Philo; Jos., Ant. 12, 38; 110 e outros; Just., A I, 4, 9 e outros; Tat., Ath.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:28</a>.</p><p class=\"entry-text\">② Aquele que faz o que é prescrito, praticante, com gen. objetivo (cf. 1 Macc 2:67) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:11</a>. (Oposto a <span class=\"greek\">ἀκροατής</span>) <span class=\"greek\">π</span>. <span class=\"greek\">λόγου</span> 1:22f. <span class=\"greek\">π</span>. <span class=\"greek\">ἔργου</span> um praticante que age (oposto: um ouvinte esquecido) v. 25.—B. 1299. DELG s.v. <span class=\"greek\">ποιέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποικιλία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποικιλία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ποικιλός</span>; Pla., X. et al.; inscrições, PTebt 703, 93 [III a.C.]; LXX; EpArist 56; Philo, Tat.), estado de variações de aspecto, aparência multicolorida, variedade, diversidade <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀρέων</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. Hs 9, 18, 5. Pl. (Isocr. 5, 27) <span class=\"greek\">αἱ</span> <span class=\"greek\">ποικιλίαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span> a diversidade de disposições mentais entre as nações 9, 17, 2. <span class=\"greek\">αἱ</span> <span class=\"greek\">ποικιλίαι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λίθων</span> os diversos aspectos das pedras 9, 6, 4.—DELG s.v. <span class=\"greek\">ποικίλος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποικίλος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποικίλος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom.+)</p><p class=\"entry-text\">① Relativo à existência em diversos tipos ou modos, diversificado, multiforme (Pind. et al.; 2 Macc 15:21; EpArist 78; Philo; Jos., Bell. 3, 393, Ant. 10, 142) <span class=\"greek\">ἄνθη</span> (Ps.-Pla., Axioch. 13 p. 371c) ApcPt 3:10. <span class=\"greek\">ἀρνήσεις</span> Hs 8, 8, 4. <span class=\"greek\">ἀσθένειαι</span> 6, 3, 4c. <span class=\"greek\">βάσανοι</span> muitos/diversos tipos de tormentos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; Hs 6, 3, 4b; de tortura MPol 2:4. <span class=\"greek\">βοτάναι</span> Hm 10, 1, 5. <span class=\"greek\">δυνάμεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:4</a>. <span class=\"greek\">ἔθνη</span> Hs 9, 17, 2b; <span class=\"greek\">ἐπιθυμίαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:6</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:3</a>. <span class=\"greek\">ἰδέαι</span> Hs 9, 17, 1. <span class=\"greek\">καρποί</span> 9, 28, 3; Dg 12:1. <span class=\"greek\">νόσοι</span> (Tat. 20, 2; Philo, Omn. Prob. Lib. 58 <span class=\"greek\">νοσήματα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:40</a>. <span class=\"greek\">ὄρη</span> Hs 9, 17, 2ac; 3. <span class=\"greek\">πειρασμοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:6</a> (<span class=\"greek\">πολλοῖς</span> P72). <span class=\"greek\">πονηρίαι</span> Hs 9, 18, 3. <span class=\"greek\">πραγματεῖαι</span> (cf. Philo, In Flacc. 3) 9, 20, 1. <span class=\"greek\">τιμωρίαι</span> 6, 3, 3; 4a. <span class=\"greek\">τρυφαί</span> m 6, 2, 5. <span class=\"greek\">π</span>. <span class=\"greek\">χάρις</span> <span class=\"greek\">θεοῦ</span> a graça de Deus que se manifesta de diversos modos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:10</a>. <span class=\"greek\">χρόαι</span> Hs 9, 4, 5ac. Com <span class=\"greek\">ξένος</span>: <span class=\"greek\">διδαχαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:9</a> (v. também 2b abaixo). Com <span class=\"greek\">πολύς</span> (Diod S 5, 62, 1 <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ποικίλοι</span> <span class=\"greek\">λόγοι</span>=muitos e variados relatos; 17, 13, 1; Maximus Tyr. 11, 11e; Ps.-Plut., Hom. 122) Hm 4, 2, 3; Hs 9, 20, 2. <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλαῖ</span> <span class=\"greek\">θλίψεσι</span> <span class=\"greek\">π</span>. em muitos tipos de aflições 7:4.</p><p class=\"entry-text\">② Relativo à existência em diversos aspectos.</p><p class=\"entry-text\">ⓐ De coisas, multicolorido, variegado (Hom.+; Polyaenus 6, 1, 4; Lucian, Deor. Conc. 10; PGM 4, 2709; LXX [Gen 37:3 e outros]; TestJob 46:7; TestZeb 1:3; Jos., Ant. 11, 235). Este sentido deve ser preferido em <span class=\"greek\">οἱ</span> <span class=\"greek\">λίθοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. as pedras multicoloridas (JosAs 2:3; 13:5; IG IV2/1, 106 I, 96; 113 [IV a.C.]) Hs 9, 4, 5b.</p><p class=\"entry-text\">ⓑ De pessoas, especialmente em referência a modos tortuosos de pensar, palavras e ações, extensão fig. de 2a: ambíguo, astuto, ardiloso, enganador (Hes. et al.; Trag.; Pind., N. 5, 28 <span class=\"greek\">βουλεύματα</span>; Aristoph., Thesm. 438 <span class=\"greek\">λόγοι</span>; Polyb. 8, 18, 4 <span class=\"greek\">Κρὴς</span> <span class=\"greek\">ὑπάρχων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">ποικίλος</span>; Just., D. 134, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:9</a> (v. também 1 acima). <span class=\"greek\">ἀπατη</span>[<span class=\"greek\">λοὺς</span>] <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>. … <span class=\"greek\">λόγους</span> AcPl Ox 6, 12 (restaurado segundo Aa I 241, 14).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποιμαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποιμαίνω</span> (<span class=\"greek\">ποιμήν</span>) fut. <span class=\"greek\">ποιμανῶ</span>; 1º aor. <span class=\"greek\">ἐποίμανα</span> Ps 77:72, imper. 2ª pess. pl. <span class=\"greek\">ποιμάνατε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:2</a>; fut. pass. 2ª pess. sing. <span class=\"greek\">ποιμανθήσῃ</span> Ps 36:3 (Hom.+) ‘apascentar, agir como pastor’.</p><p class=\"entry-text\">① Exercer a função de cuidador de ovelhas, pastorear, cuidar, (conduzir ao) pasto (Did., Gen. 60, 12), com ac. (Jos., Ant. 2, 264) <span class=\"greek\">π</span>. <span class=\"greek\">ποίμνην</span> apascentar um rebanho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7</a>. Uso absoluto (Demetr.: 722 Fgm. 1, 13 Jac.; Jos., Ant. 1, 309) <span class=\"greek\">δοῦλος</span> <span class=\"greek\">ποιμαίνων</span> um escravo que apascenta ovelhas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:7</a>.—Dalman (conforme citado sob <span class=\"greek\">ἀμφιβάλλω</span>).</p><p class=\"entry-text\">② Zelar por outras pessoas, pastorear, acerca da atividade que protege, rege, governa e promove o desenvolvimento, extensão fig. de 1:</p><p class=\"entry-text\">ⓐ No sentido de conduzir, guiar ou governar (Eur., Fgm. 744 TGF <span class=\"greek\">στρατόν</span>; Ps.-Lucian, Amor. 54 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀμαθεῖς</span>).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com os pormenores da imagem figurada em primeiro plano: acerca da direção de uma congregação, <span class=\"greek\">ποιμαίνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ποίμνιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> apascentar o rebanho de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:2</a> (PsSol 17:40 <span class=\"greek\">ποιμαίνων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ποίμνιον</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαιοσύνῃ</span>). <span class=\"greek\">ποίμαινε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρόβατά</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:16</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com os pormenores da imagem figurada relegados a segundo plano (cf. 1 Ch 11:2; Mi 7:14; Jer 23:2): acerca da administração de uma congregação, <span class=\"greek\">ποιμ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:28</a>.—Do Messias, <span class=\"greek\">ποιμανεῖ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λαόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">Ἰσραήλ</span> (cf. 2 Km 5:2; 7:7.—Himerius, Or. 39 [=Or. 5], 8 <span class=\"greek\">Ἀττικὴ</span> <span class=\"greek\">Μοῦσα</span> <span class=\"greek\">ποιμαίνει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>, isto é, Tessalônica) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a>. Da morte: <span class=\"greek\">θάνατος</span> <span class=\"greek\">ποιμανεῖ</span> <span class=\"greek\">αὐτούς</span> 1 Cl 51:4 (Ps 48:15). Esta última passagem constitui uma transição para várias outras nas quais</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. A atividade como ‘pastor’ produz resultados destrutivos (cf. Jer 22:22 e v. ELohmeyer, Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:27</a>) <span class=\"greek\">ποιμανεῖ</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥάβδῳ</span> <span class=\"greek\">σιδηρᾷ</span> (segundo Ps 2:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:27</a>; 12:5; 19:15 (cf. Heraclitus Fgm. 11 <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἑρπετὸν</span> <span class=\"greek\">πληγῇ</span> <span class=\"greek\">νέμεται</span>=tudo o que rasteja é apascentado mediante um golpe [proveniente de Deus]. Pla., Critias 109b faz alusão a isso).</p><p class=\"entry-text\">ⓑ Proteger, cuidar, nutrir (Aeschyl., Eumen. 91 <span class=\"greek\">ἱκέτην</span>; Pla., Lys. 209a <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>) <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:17</a> (cf. Ps 22:1; Ezk 34:23). <span class=\"greek\">π</span>. <span class=\"greek\">ἑαυτόν</span> cuidar de si mesmo, isto é, cuidar exclusivamente de si mesmo (cf. Ezk 34:2) Jd 12.—B. 146. DELG s.v. <span class=\"greek\">ποιμήν</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποιμενικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποιμενικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">ποιμήν</span>; Pla. et al.; poetas desde Theocr. 1, 23. Em prosa: Maximus Tyr. 20, 6b; 38, 2a; Philostrat., Imag. 2, 18 p. 370, 9; LXX; Philo; Jos., Ant. 6, 185), relativo a um pastor (Vi. Aesopi W 75 P. <span class=\"greek\">τὸ</span> <span class=\"greek\">ποιμενικὸν</span> <span class=\"greek\">σχῆμα</span>) <span class=\"greek\">σχήματι</span> <span class=\"greek\">ποιμενικῷ</span> em traje de pastor Hv 5:1.—DELG s.v. <span class=\"greek\">ποιμήν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποιμήν, ένος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποιμήν</span>, <span class=\"greek\">ένος</span>, <span class=\"greek\">ὁ</span> (v. os dois artigos anteriores; Hom.+; papiros, LXX; JosAs; ApcEl [PSI I, 7 verso, 1]; AscIs, ApcrEzk, Philo; Jos., Ant. 8, 404 e outros)</p><p class=\"entry-text\">① Aquele que apascenta ovelhas, pastor, pastor de ovelhas (Demetr.: 722 Fgm. 1, 13 Jac., nômades; Theoph. Ant. 2, 35 [p. 190, 8]. Em imagem figurada ou parábola: Orig., C. Cels. 4, 17, 21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:36</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:34</a> (Num 27:17); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:32</a>; GJs 4:3; 18:3 (códices). Dos pastores por ocasião do nascimento de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:8</a>, 15, 18, 20 (v. HGressmann, Das Weihnachtsevangelium 1914 [sobre isso CClemen, StKr 89, 1916, 237–52]; JGeffcken, D. Hirten auf dem Felde: Her 49, 1914, 321–51 [contra ele JKroll, Her 50, 1915, 137ff]; Clemen2 1924, 195; 203ff; IHarrie, Die Anbetung der Hirten: ARW 23, 1925, 369–82; RBultmann, Gesch. d. Syn. Trad.2 ’31, 323–6; GErdmann, D. Vorgesch. d. Lk u. Mt ’32; ADeissmann, D. Anbetung d. Hirten u. d. Anbetung d. Weisen: Lutherring 16, ’35, 377–82).—Em linguagem figurada, com predomínio dos pormenores: <span class=\"greek\">πατάξω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ποιμένα</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">διασκορπισθήσονται</span> (v.l. e também mais correta gramaticalmente:-<span class=\"greek\">θήσεται</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ποίμνης</span> (cf. Zech 13:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:27</a>; B 5:12. De Cristo em imagem figurada desenvolvida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:2</a>, 7 v.l., 16; (oposto a <span class=\"greek\">ὁ</span> <span class=\"greek\">μισθωτός</span>) v. 12; <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιμὴν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καλός</span> vv. 11ab, 14 (Maximus Tyr. 6, 7d Ciro é chamado <span class=\"greek\">ποιμὴν</span> <span class=\"greek\">ἀγαθός</span>, porque protege o ‘rebanho’ persa dos ‘lobos’ bárbaros).</p><p class=\"entry-text\">② Aquele que exerce a função de guardião ou dirigente, pastor, extensão fig. de 1 (Diog. L. 9, 40 Demócrito é chamado <span class=\"greek\">ποιμὴν</span> [=guardião] <span class=\"greek\">μύθων</span>)</p><p class=\"entry-text\">ⓐ Especialmente frequente em Hermas (Leutzsch, Hermas 439f n. 546)</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Como o anjo do arrependimento e portador de uma revelação (MDibelius, Der Offenbarungsträger im ‘Hirten’ des H.: Harnack-Ehrung 1921, 105–18; Rtzst., Erlösungsmyst. 1921, 149) Hv 5:3, 7; Hs 2:1; 5, 1, 1; 8, 1, 4; 18; 8, 2, 5f; 8; 8, 4, 1; 8, 5, 1; 6; 8, 6, 1; 9, 1, 1; 9, 2, 6; 9, 5, 1; 7; 9, 7, 1; 3f; 9, 8, 1; 9, 9, 5–7; 9, 10, 1; 4; 6; 9, 11, 1; 8; 10, 3, 4f [=POxy 404 recto C, 15; 20 restaurado].</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Na visão dos pastores Hs 6, 1, 5f; 6, 2, 1; 5f; 6, 3, 2; 7:1.</p><p class=\"entry-text\">ⓑ Daqueles que dirigem comunidades/congregações/igrejas cristãs</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Deus (Philo, Agr. 51; Aberciusins. 3 <span class=\"greek\">π</span>. <span class=\"greek\">ἁγνός</span>) IRo 9:1.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Cristo <span class=\"greek\">τὸν</span> <span class=\"greek\">ποιμένα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προβάτων</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μέγαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:20</a> (RGyllenberg, D. Christol. des Hb: ZST 11, ’34, 662–90). <span class=\"greek\">τὸν</span> <span class=\"greek\">ποιμένα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπίσκοπον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:25</a> (cf. Philo, Mut. Nom. 116, acerca do <span class=\"greek\">θεῖος</span> <span class=\"greek\">λόγος</span>; Ezk 34:23). <span class=\"greek\">ποιμ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span> MPol 19:2. V. acima 1, fim, e o excurso do Hdb. após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:21</a>; Bultmann 276–93; JQuasten, Hlg. Überliefg. (editado por OCasel) ’38, 51–58 (helenístico e cristão primitivo); WJost, Poimen. D. Bild v. Hirten in d. bibl. Überl. u. s. christol. Bed., diss. Giessen ’39; TKempf, Christus der Hirt ’42; VMuller, Prehistory of the Good Shepherd: JNES 3, ’44, 87–90.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Dirigentes humanos (sobre ‘pastores’ como fundadores e tiasarcas temporários [dirigentes] de associações religiosas gregas, v. EMaass, Orpheus 1895, 181; Himerius, Or. 54 [=Or. 15], ao saudar seus alunos recém-chegados, compara os professores a pastores [<span class=\"greek\">ἀγελάρχαι</span>] e os alunos ao rebanho [<span class=\"greek\">ἀγέλη</span> alternando com <span class=\"greek\">ποίμνιον</span> §2]. V. também Jer 2:8; 3:15; Ezk 34:2) pastor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:11</a> (com outros dirigentes da igreja). <span class=\"greek\">ὅπου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιμήν</span> (isto é, o superintendente/supervisor) <span class=\"greek\">ἐστιν</span>, <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">ἀκολουθεῖτε</span> IPhld 2:1. V. também IRo 9:1 (Ign. como ‘pastor’ da igreja síria).—EHatch/AHarnack, D. Gesellschaftsverf. der christl. Kirchen im Altertum 1883, 230; HBruders, D. Verfassung der Kirche bis zum Jahr 175 n. Chr. 1904, 190f; 371f; Harnack, D. Mission4 I 1923, 350f; NCavatassi, De Munere Pastoris in NT: Verb. Domini 29, ’51, 215–27; 275–85.—B. 149. DELG. EDNT. RAC XV 577–607. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποίμνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποίμνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ποιμήν</span>; Hom. et al.; PAmh 127, 39; Gen 32:17; TestGad 1:3; TestJos 19:5, 6 [A]; Jos., Ant. 6, 295), rebanho, especialmente de ovelhas (Diod S 4, 26, 2 <span class=\"greek\">ποίμνας</span> <span class=\"greek\">προβάτων</span>; 5, 65, 2; 20, 8, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7b</a>. <span class=\"greek\">ποιμαίνειν</span> <span class=\"greek\">ποίμνην</span> v. 7a.—Em linguagem figurada: em referência aos discípulos de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:31</a>; B 5:12 (ambos=Zech 13:7 A); à igreja e a Jesus como seu cabeça <span class=\"greek\">μία</span> <span class=\"greek\">ποίμνη</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">ποιμήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:16</a> (Maximus Tyr. 35, 2g <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγέλῃ</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ποιμένι</span> <span class=\"greek\">ἑνί</span>; Philo, Agr. 51 Deus como <span class=\"greek\">ποιμήν</span> conduz o mundo inteiro como <span class=\"greek\">ποίμνη</span>).—DELG s.v. <span class=\"greek\">ποιμήν</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποίμνιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποίμνιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">ποιμήν</span> por intermédio de <span class=\"greek\">ποίμνη</span>; Soph., Hdt. et al.; PRyl 114, 20; LXX; PsSol 17:40; TestSol 10, 52 C; Test12Patr, Philo)</p><p class=\"entry-text\">① Um conjunto de animais de uma espécie determinada, rebanho, especialmente de ovelhas (Ps.-Apollod., Epit. 7, 5, 8; Tzetzes sobre Lycophron 344; EpArist 170; Jos., Ant. 8, 404; 18, 316; Test12Patr) MPol 14:1; GJs 4:2, 4.</p><p class=\"entry-text\">② Um grupo definido de pessoas sob um dirigente, rebanho, extensão fig. de 1 (Hippocr., Ep. 1, 2; Themist., Or. 23 p. 289)</p><p class=\"entry-text\">ⓐ Na visão dos pastores (<span class=\"greek\">ποιμήν</span> 2a<span class=\"greek\">β</span>) Hs 6, 1, 6.</p><p class=\"entry-text\">ⓑ Da comunidade cristã (como do povo de Israel no AT: Jer 13:17 <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">κυρίου</span>; Zech 10:3 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:28f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:3</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> v. 2. <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> 1 Cl 44:3; 54:2; 57:2; cf. 16:1. Dos discípulos de Jesus (Liban., Or. 58, 36, acerca dos alunos de um sofista; Himerius, Or. 54 [=Or. 15], 2, acerca dos ouvintes) <span class=\"greek\">τὸ</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">π</span>. (nom. com art. em lugar do voc. B-D-F §147 apênd.; Rob. 465) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:32</a>.—DELG s.v. <span class=\"greek\">ποιμήν</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποῖος, α, ον</h1><div class=\"entry-meta\"><span>pronome interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ποῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Hom.+), pron. interrog., em orações interrogativas diretas e indiretas.</p><p class=\"entry-text\">① Referência interrogativa a classe ou espécie, de que espécie?</p><p class=\"entry-text\">ⓐ Empregado com um substantivo (B-D-F §298, 2; cf. Rob. 740)</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Ao lado de <span class=\"greek\">τίς</span> (Hdt. 7, 21, 1; Herodas 6, 74f; Maximus Tyr. 33, 5a <span class=\"greek\">τίνα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποῖον</span> <span class=\"greek\">τύραννον</span>; PTebt 25, 18 [117 a.C.]; BGU 619, 8) <span class=\"greek\">εἰς</span> <span class=\"greek\">τίνα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ποῖον</span> <span class=\"greek\">καιρόν</span> para que tempo ou que espécie de tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:11</a> (cf. UPZ 65, 52 [154 a.C.] <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ποίου</span> <span class=\"greek\">χρόνου</span>=desde que tempo). <span class=\"greek\">ποῖον</span> <span class=\"greek\">οἶκον</span> … <span class=\"greek\">ἢ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">τόπος</span> … ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:49</a>; B 16:2 (ambos Is 66:1; v. ed. JZiegler). <span class=\"greek\">τίς</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐγέννησεν</span>; <span class=\"greek\">ποία</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μήτρα</span> <span class=\"greek\">ἐξέφυσέν</span> <span class=\"greek\">με</span>; quem me gerou, e que espécie de ventre me deu à luz? GJs 3:1.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em pergunta direta (3 Km 22:24) <span class=\"greek\">διὰ</span> <span class=\"greek\">ποίου</span> <span class=\"greek\">νόμου</span>; por que espécie de lei? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>. <span class=\"greek\">ποίῳ</span> <span class=\"greek\">σώματι</span>; com que espécie de corpo? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:35</a>. <span class=\"greek\">ποίῳ</span> <span class=\"greek\">προσώπῳ</span>; com que espécie de semblante ou expressão? GJs 13:1. <span class=\"greek\">ποῖον</span> <span class=\"greek\">κλέος</span>; ironicamente, que espécie de mérito? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:20</a>; semelhantemente <span class=\"greek\">ποία</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">ἐστίν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:32</a>, 33, 34; cf. D 1:3.—1 Cl 28:2; 2 Cl 1:5; 6:9; Hv 1, 2, 1; m 12, 1, 3a; Hs 6, 5, 5; 9, 13, 3.—Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:14</a>, v. <span class=\"greek\">γ</span>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Em pergunta indireta (Archimed. II 416, 6 Heib. <span class=\"greek\">ποῖαι</span> <span class=\"greek\">γωνίαι</span>) <span class=\"greek\">ποίῳ</span> <span class=\"greek\">θανάτῳ</span> (por) que espécie de morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:33</a>; 18:32; 21:19 (cf. Just., D. 104, 1 <span class=\"greek\">διὰ</span> <span class=\"greek\">ποίου</span> <span class=\"greek\">θανάτου</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:55</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:14</a> (pode ser entendido como pergunta direta; v. Windisch ad loc.); 1 Cl 38:3a; Hm 4, 2, 3; 12, 1, 3b.</p><p class=\"entry-text\">ⓑ Sem substantivo <span class=\"greek\">ποῖοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τίνες</span> 1 Cl 38:3b. No predicado <span class=\"greek\">οἱ</span> <span class=\"greek\">καρποὶ</span> <span class=\"greek\">φανεροῦνται</span> <span class=\"greek\">ποῖοί</span> <span class=\"greek\">τινές</span> <span class=\"greek\">εἰσιν</span> Hs 4:3.</p><p class=\"entry-text\">② (=<span class=\"greek\">τίς</span>) qual?, que?</p><p class=\"entry-text\">ⓐ Com substantivo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em pergunta direta (Theopomp. [IV a.C.]: 115 Fgm. 263a Jac.; 2 Km 15:2; 3 Km 13:12; Jon 1:8; Jos., Ant. 15, 137) <span class=\"greek\">ποία</span> <span class=\"greek\">ἐντολή</span>; qual mandamento? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:32</a>. <span class=\"greek\">ποίῳ</span> <span class=\"greek\">τρόπῳ</span>; de que modo? Hv 1, 1, 7; cf. m 12, 3, 1. <span class=\"greek\">εἰς</span> <span class=\"greek\">ποῖον</span> <span class=\"greek\">τόπον</span> v 3, 1, 3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em pergunta indireta (Aeschin., In Ctesiph. 24; Tob 5:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:42f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:3</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">ποίας</span> <span class=\"greek\">ἐπαρχίας</span> <span class=\"greek\">ἐστίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:34</a>.—Hv 4, 3, 7; m 12, 3.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Em alguns casos <span class=\"greek\">π</span>. ocupa o lugar do gen. do interrog. <span class=\"greek\">τίς</span> (tanto em perguntas diretas como indiretas. Cf. Chariton 4, 4, 3 Blake <span class=\"greek\">ποίᾳ</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">πεποιθώς</span>;) <span class=\"greek\">ἐν</span> <span class=\"greek\">ποίᾳ</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ποίῳ</span> <span class=\"greek\">ὀνόματι</span>; pelo poder de quem ou em nome de quem? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:7</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ποίᾳ</span> <span class=\"greek\">ἐξουσίᾳ</span>(;) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:23</a>, 24, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:28</a>, 29, 33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:2</a>, 8.</p><p class=\"entry-text\">ⓑ Sem substantivo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Que, contudo, pode ser suprido pelo contexto (Jos., C. Ap. 1, 254 <span class=\"greek\">ποίους</span>;): <span class=\"greek\">ποίας</span>; (isto é, <span class=\"greek\">ἐντολάς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:18</a>. <span class=\"greek\">ποῖα</span> (isto é, <span class=\"greek\">γενόμενα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:19</a>. <span class=\"greek\">ποίαν</span>; (isto é, <span class=\"greek\">ἀντιμισθίαν</span>) 2 Cl 9:8. <span class=\"greek\">ποίους</span> (isto é, <span class=\"greek\">ἀνθρώπους</span>) <span class=\"greek\">βαστάζει</span> Hs 9, 14, 6. No predicado: <span class=\"greek\">τὰ</span> <span class=\"greek\">ξηρὰ</span> (isto é, <span class=\"greek\">δένδρα</span>) <span class=\"greek\">ποῖά</span> <span class=\"greek\">ἐστιν</span> 3:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Gen. de lugar, com elipse (B-D-F §186, 1; Mlt. 73) <span class=\"greek\">ποίας</span> (isto é, <span class=\"greek\">ὁδοῦ</span>) por que caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:19</a>.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολεμέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολεμέω</span> (<span class=\"greek\">πόλεμος</span>) fut. <span class=\"greek\">πολεμήσω</span>; 1º aor. <span class=\"greek\">ἐπολέμησα</span>. Pass.: 1º fut. <span class=\"greek\">πολεμηθήσομαι</span>; aor. 3ª pess. pl. <span class=\"greek\">ἐπολεμήθησαν</span> Judg 5:20 v.l. (Soph., Hdt.+).</p><p class=\"entry-text\">① Guerrear</p><p class=\"entry-text\">ⓐ Voz ativa, fazer guerra, combater <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> contra ou com (contra) alguém (<span class=\"greek\">μετά</span> A2c<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:7a</a>; 13:4; 17:14. <span class=\"greek\">π</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ῥομφαίᾳ</span> guerrear contra alguém com a espada 2:16 (para <span class=\"greek\">πολ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ῥομφ</span>., cf. 1 Macc 3:12). <span class=\"greek\">πολ</span>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> guerrear contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:7a</a> t.r. Com ac. <span class=\"greek\">μέλλει</span>] <span class=\"greek\">γὰρ</span> [<span class=\"greek\">ἐν</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">ἡμέρᾳ</span>] <span class=\"greek\">πολεμῖν</span> <span class=\"greek\">τὸ</span>[<span class=\"greek\">ν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρί</span>] AcPl Ha 9, 14 (provavelmente por erro em lugar de <span class=\"greek\">ἀπολλύειν</span>; v. Schmidt ad loc.). Uso absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:7b</a>; (com <span class=\"greek\">κρίνειν</span>) 19:11. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πολεμεῖν</span> <span class=\"greek\">αὐτούς</span> porque foram à guerra B 16:4.</p><p class=\"entry-text\">ⓑ Voz passiva, ser alvo de guerra, ser combatido <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> (Demosth. 9, 9; Jos., Ant. 9, 255; Just., D. 49, 8) B 12:2a. Uso absoluto (Thu. 1, 68, 3; X., Hell. 7, 4, 20) ibid. v. 2b.</p><p class=\"entry-text\">② Estar em oposição a, ser hostil, em linguagem figurada militar, acerca da atitude hostil dos judeus para com os cristãos <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">Ἰουδαίων</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀλλόφυλοι</span> <span class=\"greek\">πολεμοῦνται</span> Dg 5:17 (acerca da prática de atos hostis Vi. Aesopi I c. 127; Jos., Vi. 244; acerca da perseguição por gentios Just., A II, 12, 6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:13</a>, 23 (ambas v.l.).—Dos israelitas impenitentes <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">πολεμηθήσονται</span> B 12:2c. Das disputas dos cristãos entre si <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:2</a> (Diod S 13, 84, 4; Sb 4317, 12).—<span class=\"greek\">τὸ</span> <span class=\"greek\">ζῆλος</span> <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">πολεμεῖ</span> o desejo ardente (de martírio) exerce forte pressão sobre mim ITr 4:2 (o ac. como em Dinarchus 1, 36; Diod S 2, 37, 3; Chariton 7, 5, 3).—Da atitude hostil da <span class=\"greek\">σάρξ</span> para com a <span class=\"greek\">ψυχή</span> Dg 6:5 (Herm. Wr. 392, 3 Sc. acerca da <span class=\"greek\">ψυχή</span>: <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἑαυτῇ</span> <span class=\"greek\">πολεμῆσαι</span> <span class=\"greek\">δεῖ</span>).—B. 1370. DELG s.v. <span class=\"greek\">πελεμίζω</span> II. Frisk s.v. <span class=\"greek\">πόλεμος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόλεμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόλεμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. artigo anterior; Hom.+; empréstimo no vocabulário rabínico).</p><p class=\"entry-text\">① Conflito militar</p><p class=\"entry-text\">ⓐ Guerra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:34</a>. <span class=\"greek\">πόλεμοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀκοαὶ</span> <span class=\"greek\">πολέμων</span> guerras e rumores de guerras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:7</a>. Com <span class=\"greek\">ἀκαταστασίαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:9</a>. Com <span class=\"greek\">λιμός</span> 1 Cl 56:9 (Job 5:20). <span class=\"greek\">συμβαλεῖν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πόλεμον</span> fazer guerra contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:31</a> (<span class=\"greek\">συμβάλλω</span> 5a). <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">πόλεμον</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> (v. <span class=\"greek\">μετά</span> A2c<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:7</a>; 12:17; 13:7 (Da 7:21 Theod.); 19:19. AFridrichsen, Krig och fred i Nya Testamentet ’40.</p><p class=\"entry-text\">ⓑ De um único enfrentamento, batalha, combate (Hom., Hes.; Diod S 22, 13, 5; Appian, Bell. Civ. 3, 67 §278; Polyaenus, Exc. 13, 3; 9; 3 Km 22:34; 1 Macc 4:13; 10:78; JosAs 26:5; Jos., Bell. 3, 189) <span class=\"greek\">παρασκευάζεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">π</span>. preparar-se para a batalha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:8</a>. De cavalos (Dio Chrys. 46 [63], 4) <span class=\"greek\">ἑτοιμάζεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">π</span>. ser preparado para a batalha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:7</a>. <span class=\"greek\">τρέχειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">π</span>. precipitar-se na batalha v. 9. Cf. 12:7; 16:14; 20:8.</p><p class=\"entry-text\">② Estado de hostilidade/antagonismo, contenda, conflito, querela, extensão fig. de 1 (desde Soph., El. 218; Pla. [p. ex., Phd. 66c]; Epict. 3, 20, 18; TestJob 4:4; TestGad 5:1; ApcMos 28; Philo, Praem. 91, Gig. 51; Tat. 26, 3), acerca de poderes terrenos e celestiais IEph 13:2 (oposto a <span class=\"greek\">εἰρήνη</span>).—Da situação em Corinto 1 Cl 3:2; 46:5. Pl. (com <span class=\"greek\">μάχαι</span>; cf. Dio Chrys. 11 [12], 78; Himerius, Or. [Ecl.] 3, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:1</a>.—B. 1374. DELG s.v. <span class=\"greek\">πελεμίζω</span> II. Frisk. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολιά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (substantivação fem. do adj. [em uso desde Hom.] <span class=\"greek\">πολιός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> ‘grisalho’), velhice (Cornutus 23 p. 44, 19; Lucian, Philops. 23; Ps.-Lucian, Amor. 12; Themist. p. 163d; 182b; LXX; Philo, Spec. Leg. 2, 238) <span class=\"greek\">ἀγαθὴ</span> <span class=\"greek\">πολ</span>. (cf. Judg 8:32 A <span class=\"greek\">πολιὰ</span> <span class=\"greek\">ἀγαθή</span>) MPol 13:2 v.l. (em lugar de <span class=\"greek\">πολιτεία</span>).—DELG s.v. <span class=\"greek\">πολιός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0291-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολιορκία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολιορκία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πόλις</span>, cf. <span class=\"greek\">ἕρκος</span> ‘recinto’; Hdt. et al.; inscrições; Sb 3776, 4 [I a.C.]; LXX; TestSol 10:36 C; TestJud 23:3; Jos., Bell. 3, 183, Vi. 329), ato de cercar hostilmente uma área durante um período prolongado, cerco, com <span class=\"greek\">θλῖψις</span> 1 Cl 57:4 (Pr 1:27). O emprego metafórico posterior, aflição, tribulação (Plut., Sulla 25, 4 Z. v.l.), é certamente o que se deve entender aqui.—DELG s.v. <span class=\"greek\">πόλις</span>.</p></section></article>"};
